
from io import BytesIO
from datetime import datetime

import pandas as pd

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib.units import cm
from reportlab.platypus import (
    SimpleDocTemplate,
    Paragraph,
    Spacer,
    Table,
    LongTable,
    TableStyle
)


def generate_pdf(results, source_name, contamination):

    buffer = BytesIO()

    document = SimpleDocTemplate(
        buffer,
        pagesize=landscape(A4),
        rightMargin=1.5 * cm,
        leftMargin=1.5 * cm,
        topMargin=1.5 * cm,
        bottomMargin=1.5 * cm
    )

    styles = getSampleStyleSheet()
    content = []

    # Menghitung ringkasan
    total = len(results)

    normal = (
        results["anomaly_status"] == "Normal"
    ).sum()

    anomaly = (
        results["anomaly_status"] == "Anomaly"
    ).sum()

    percentage = (
        anomaly / total * 100 if total > 0 else 0
    )

    # Judul laporan
    content.append(
        Paragraph(
            "AI ANOMALY DETECTOR",
            styles["Title"]
        )
    )

    content.append(
        Paragraph(
            "Machine Learning Analysis Report",
            styles["Heading2"]
        )
    )

    content.append(Spacer(1, 15))

    # Informasi analisis
    information = [
        ["Dataset", str(source_name)],
        [
            "Tanggal Analisis",
            datetime.now().strftime("%d-%m-%Y %H:%M:%S")
        ],
        ["Metode", "Isolation Forest"],
        ["Contamination", f"{contamination * 100:.0f}%"]
    ]

    info_table = Table(
        information,
        colWidths=[4 * cm, 12 * cm]
    )

    info_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#dbeafe")),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.HexColor("#1e293b")),
        ("FONTNAME", (0, 0), (-1, -1), "Helvetica"),
        ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
        ("PADDING", (0, 0), (-1, -1), 7),
    ]))

    content.append(info_table)
    content.append(Spacer(1, 20))

    # Ringkasan hasil
    content.append(
        Paragraph("Analysis Summary", styles["Heading2"])
    )

    summary = [
        ["Total Data", "Normal", "Anomaly", "Anomaly Percentage"],
        [
            str(total),
            str(normal),
            str(anomaly),
            f"{percentage:.2f}%"
        ]
    ]

    summary_table = Table(
        summary,
        colWidths=[5 * cm] * 4
    )

    summary_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1e3a8a")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("BACKGROUND", (0, 1), (-1, -1), colors.HexColor("#eff6ff")),
        ("TEXTCOLOR", (0, 1), (-1, -1), colors.HexColor("#1e293b")),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
        ("PADDING", (0, 0), (-1, -1), 9),
    ]))

    content.append(summary_table)
    content.append(Spacer(1, 20))

    # Detail hasil analisis
    content.append(
        Paragraph("Detection Results", styles["Heading2"])
    )

    # Maksimal 8 kolom agar tabel tetap terbaca
    columns = list(results.columns)[:8]

    table_data = [columns]

    for _, row in results[columns].iterrows():
        values = []

        for column in columns:
            value = row[column]

            if column == "anomaly_score":
                value = f"{value:.5f}"

            values.append(str(value))

        table_data.append(values)

    result_table = LongTable(
        table_data,
        repeatRows=1,
        hAlign="LEFT"
    )

    result_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1e3a8a")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 8),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.grey),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [
            colors.white,
            colors.HexColor("#eff6ff")
        ]),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("PADDING", (0, 0), (-1, -1), 6),
    ]))

    content.append(result_table)

    content.append(Spacer(1, 20))

    content.append(
        Paragraph(
            "Generated by AI Anomaly Detector | "
            "Powered by Python and Scikit-learn",
            styles["Normal"]
        )
    )

    document.build(content)

    pdf_bytes = buffer.getvalue()
    buffer.close()

    return pdf_bytes
